import {
    type CommandExample,
    catchError,
    createHiddenDeprecatedTenantOption,
    extractErrorMessage,
    OutputFormatter,
    processContext,
    RESULTS,
} from "@uipath/common";
import type {
    EntityCreateFieldOptions,
    EntityServiceModel,
    EntityUpdateByIdOptions,
    ExternalSourceFields,
    RawEntityGetResponse,
} from "@uipath/uipath-typescript";
import { EntityFieldDataType } from "@uipath/uipath-typescript";
import { type Command, Option } from "commander";
import { readJsonInput } from "../utils/input";
import { fail, requireDestructiveConfirmation } from "../utils/output";
import { connectOrFail } from "../utils/sdk-client";

interface ListOptions {
    tenant?: string;
    nativeOnly?: boolean;
}

interface GetOptions {
    tenant?: string;
}

interface CreateOptions {
    tenant?: string;
    file?: string;
    body?: string;
}

interface UpdateEntityOptions {
    tenant?: string;
    file?: string;
    body?: string;
    yes?: boolean;
    confirm?: boolean;
    reason?: string;
}

interface DeleteOptions {
    tenant?: string;
    yes?: boolean;
    confirm?: boolean;
    reason?: string;
}

